            wgpu::BindGroupLayoutEntry {
                binding: 1,
                visibility: wgpu::ShaderStages::COMPUTE,
                ty: wgpu::BindingType::Buffer {
                    ty: wgpu::BufferBindingType::Storage { read_only: true },
                    has_dynamic_offset: false,
                    min_binding_size: None,
                },
                count: None,
            },
            wgpu::BindGroupLayoutEntry {
                binding: 2,
                visibility: wgpu::ShaderStages::COMPUTE,
                ty: wgpu::BindingType::Buffer {
                    ty: wgpu::BufferBindingType::Storage { read_only: false },
                    has_dynamic_offset: false,
                    min_binding_size: None,
                },
                count: None,
            },
        ],
    });

    let pipeline_layout = device.create_pipeline_layout(&wgpu::PipelineLayoutDescriptor {
        label: Some("heat pipeline layout"),
        bind_group_layouts: &[Some(&bind_group_layout)],
        immediate_size: 0,
    });

    let pipeline = device.create_compute_pipeline(&wgpu::ComputePipelineDescriptor {
        label: Some("heat pipeline"),
        layout: Some(&pipeline_layout),
        module: &shader,
        entry_point: Some("step"),
        compilation_options: Default::default(),
        cache: None,
    });

    let params = [grid.width, grid.height];
    let params_buffer = device.create_buffer_init(&wgpu::util::BufferInitDescriptor {
        label: Some("params"),
        contents: bytemuck::cast_slice(&params),
        usage: wgpu::BufferUsages::UNIFORM,
    });

    let byte_len = (grid.cells.len() * std::mem::size_of::<u32>()) as wgpu::BufferAddress;
    let storage_usage = wgpu::BufferUsages::STORAGE
        | wgpu::BufferUsages::COPY_SRC
        | wgpu::BufferUsages::COPY_DST;
    let buffers = [
        device.create_buffer_init(&wgpu::util::BufferInitDescriptor {
            label: Some("grid a"),
            contents: bytemuck::cast_slice(&grid.cells),
            usage: storage_usage,
        }),
        device.create_buffer(&wgpu::BufferDescriptor {
            label: Some("grid b"),
            size: byte_len,
            usage: storage_usage,
            mapped_at_creation: false,
        }),
    ];

    // Two bind groups for ping-pong: step k reads buffers[k % 2] and writes the other.
    let bind_groups: Vec<wgpu::BindGroup> = (0..2)
        .map(|k| {
            device.create_bind_group(&wgpu::BindGroupDescriptor {
                label: Some("heat bind group"),
                layout: &bind_group_layout,
                entries: &[
                    wgpu::BindGroupEntry {
                        binding: 0,
                        resource: params_buffer.as_entire_binding(),
                    },
                    wgpu::BindGroupEntry {
                        binding: 1,
                        resource: buffers[k].as_entire_binding(),
                    },
                    wgpu::BindGroupEntry {
                        binding: 2,
                        resource: buffers[1 - k].as_entire_binding(),
                    },
                ],
            })
        })
        .collect();

    let staging = device.create_buffer(&wgpu::BufferDescriptor {
        label: Some("readback"),
        size: byte_len,
        usage: wgpu::BufferUsages::MAP_READ | wgpu::BufferUsages::COPY_DST,
        mapped_at_creation: false,
    });

    let groups_x = grid.width.div_ceil(WORKGROUP);
    let groups_y = grid.height.div_ceil(WORKGROUP);

    let mut encoder = device.create_command_encoder(&wgpu::CommandEncoderDescriptor {
        label: Some("heat encoder"),
    });
    for step in 0..grid.steps as usize {
        let mut pass = encoder.begin_compute_pass(&wgpu::ComputePassDescriptor {
            label: Some("heat step"),
            timestamp_writes: None,
        });
        pass.set_pipeline(&pipeline);
        pass.set_bind_group(0, &bind_groups[step % 2], &[]);
        pass.dispatch_workgroups(groups_x, groups_y, 1);
    }

    // After `steps` steps the newest values sit in buffers[steps % 2].
    let result = &buffers[grid.steps as usize % 2];
    encoder.copy_buffer_to_buffer(result, 0, &staging, 0, byte_len);
    queue.submit(Some(encoder.finish()));

    let (sender, receiver) = std::sync::mpsc::channel();
    staging.slice(..).map_async(wgpu::MapMode::Read, move |res| {
        let _ = sender.send(res);
    });
    device
        .poll(wgpu::PollType::wait_indefinitely())
        .map_err(|e| format!("GPU poll failed: {e}"))?;
    receiver
        .recv()
        .map_err(|e| format!("readback channel closed: {e}"))?
        .map_err(|e| format!("readback failed: {e}"))?;

    let values = {
        let view = staging.slice(..).get_mapped_range();
        bytemuck::cast_slice::<u8, u32>(&view).to_vec()
    };
    staging.unmap();

    Ok(values)
}

fn run(path: &str) -> Result<(), String> {
    let text = std::fs::read_to_string(path).map_err(|e| format!("cannot read {path}: {e}"))?;
    let grid = parse_grid(&text)?;
    let values = run_gpu(&grid)?;

    let width = grid.width as usize;
    let mut out = String::with_capacity(values.len() * 8);
    let mut sum: u64 = 0;
    for row in values.chunks(width) {
        for (i, v) in row.iter().enumerate() {
            if i > 0 {
                out.push(' ');
            }
            let _ = write!(out, "{v}");
            sum += u64::from(*v);
        }
        out.push('\n');
    }
    let _ = writeln!(out, "SUM {sum}");

    let stdout = io::stdout();
    let mut lock = stdout.lock();
    lock.write_all(out.as_bytes())
        .and_then(|()| lock.flush())
        .map_err(|e| format!("cannot write output: {e}"))
}

fn main() -> ExitCode {
    let Some(path) = std::env::args().nth(1) else {
        eprintln!("usage: heat <input-file>");
        return ExitCode::FAILURE;
    };

    match run(&path) {
        Ok(()) => ExitCode::SUCCESS,
        Err(message) => {
            eprintln!("error: {message}");
            ExitCode::FAILURE
        }
    }
}
